operations.command:
FIND(?belief.status, ?city.name) WHERE {
  ?person CONCEPT {type: "Person", key: "user_042"}
  ?belief BELIEF (?person, "ships_to", ?city)
  FILTER(?belief.status == "accepted")
  FILTER(CONTAINS(?city.name, "Tokyo") || CONTAINS(?city.attributes.description, "Tokyo"))
} LIMIT 10
